269			t.Fatalf("record after the oversized line must keep line number 2: %#v", results[1])
270		}
271		if eventOf(t, results[1])["action"] != "after" {
272			t.Fatalf("record after the oversized line must keep its content: %#v", results[1])
273		}
274	}
